package com.example.starter.exposure.web;

import com.example.starter.exposure.domain.ApplyOutcome;

/**
 * 申请曝光结果。静默判定先于额度校验：
 * <ul>
 *     <li>outcome=RESERVED 时携带预占单字段，{@code quietEndsAtUtc} 为 null；</li>
 *     <li>outcome=SUPPRESSED 时仅返回 outcome 与静默结束时刻，预占字段均为 null，
 *     不创建预占、不占两级额度、不返回 429。</li>
 * </ul>
 *
 * @param outcome        裁决结果：RESERVED 或 SUPPRESSED
 * @param reservation    预占单视图；被抑制时为 null
 * @param quietEndsAtUtc 静默结束时刻（epoch 毫秒，UTC）；未抑制时为 null
 */
public record ApplyResultResponse(
        ApplyOutcome outcome,
        ReservationResponse reservation,
        Long quietEndsAtUtc
) {
    public static ApplyResultResponse reserved(ReservationResponse reservation) {
        return new ApplyResultResponse(ApplyOutcome.RESERVED, reservation, null);
    }

    public static ApplyResultResponse suppressed(long quietEndsAtUtc) {
        return new ApplyResultResponse(ApplyOutcome.SUPPRESSED, null, quietEndsAtUtc);
    }
}

package com.example.starter.exposure.web;

import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 登记/修改访客静默设置请求。
 *
 * <p>每日静默区间以本地分钟表达，区间左闭右开，起止必须不同；
 * {@code quietStartMinute &gt; quietEndMinute} 表示跨零点（如 22:00～06:00）。</p>
 *
 * @param requestId        写操作全局唯一幂等键
 * @param visitorId        合成访客编号
 * @param utcOffsetMinutes UTC 偏移分钟，取值 −720～840
 * @param quietStartMinute 静默起始本地分钟，取值 0～1438
 * @param quietEndMinute   静默结束本地分钟，取值 0～1439，且不等于起始
 * @param allowCritical    静默时段内是否允许 CRITICAL 照常曝光
 * @param expectedVersion  访客当前设置版本；首次登记传 0，已有设置须传其最新版本，冲突返回 409
 */
public record QuietSettingsRequest(
        @NotBlank @Size(max = 64) String requestId,
        @NotBlank @Size(max = 64) String visitorId,
        @NotNull @Min(-720) @Max(840) Integer utcOffsetMinutes,
        @NotNull @Min(0) @Max(1438) Integer quietStartMinute,
        @NotNull @Min(0) @Max(1439) Integer quietEndMinute,
        @NotNull Boolean allowCritical,
        @NotNull @Min(0) Integer expectedVersion
) {
}

package com.example.starter.exposure.web;

import com.example.starter.exposure.domain.VisitorQuietSettings;

/**
 * 访客静默设置视图。
 *
 * @param visitorId        合成访客编号
 * @param utcOffsetMinutes UTC 偏移分钟（−720～840）
 * @param quietStartMinute 静默起始本地分钟（0～1438），含该时刻
 * @param quietEndMinute   静默结束本地分钟（0～1439），不含该时刻；小于起始为跨零点
 * @param allowCritical    静默时段内是否允许 CRITICAL 照常曝光
 * @param version          当前版本号，下次修改须回传
 * @param updatedAtUtc     最近修改时刻，epoch 毫秒，UTC
 */
public record QuietSettingsResponse(
        String visitorId,
        int utcOffsetMinutes,
        int quietStartMinute,
        int quietEndMinute,
        boolean allowCritical,
        int version,
        long updatedAtUtc
) {
    public static QuietSettingsResponse from(VisitorQuietSettings s) {
        return new QuietSettingsResponse(
                s.visitorId(),
                s.utcOffsetMinutes(),
                s.quietStartMinute(),
                s.quietEndMinute(),
                s.allowCritical(),
                s.version(),
                s.updatedAtUtc());
    }
}

